# File: engine.py import math from models import ArticoloMagazzino, RisultatoAnalisiScorte class MotoreCalcoloEOQ:    """Motore di calcolo per Lotto Economico (EOQ), Safety Stock e Punto di Riordino (ROP)."""    TABELLA_Z = {        0.900: 1.2816,        0.950: 1.6449,        0.975: 1.9600,        0.980: 2.0537,        0.990: 2.3263,        0.995: 2.5758,        0.999: 3.0902,    }    def __init__(self, giorni_anno: int = 365):        self.giorni_anno = giorni_anno    def ottieni_fattore_z(self, livello_servizio: float) -> float:        """Restituisce il quantile z della normale standard per il livello di servizio CSL."""        if not (0.5 < livello_servizio < 1.0):            raise ValueError("Il livello di servizio deve essere compreso tra 0.50 e 0.999.")        chiave = round(livello_servizio, 3)        if chiave in self.TABELLA_Z:            return self.TABELLA_Z[chiave]        # Approssimazione razionale di Abramowitz & Stegun per quantili intermedi        p = 1.0 - livello_servizio        t = math.sqrt(-2.0 * math.log(p))        c0, c1, c2 = 2.515517, 0.802853, 0.010328        d1, d2, d3 = 1.432788, 0.189269, 0.001308        return t - (c0 + c1 * t + c2 * t**2) / (1.0 + d1 * t + d2 * t**2 + d3 * t**3)    def calcola_eoq(self, art: ArticoloMagazzino) -> float:        """Calcola EOQ = sqrt((2 * D * S) / H)."""        return math.sqrt((2.0 * art.domanda_annua * art.costo_setup) / art.costo_mantenimento)    def calcola_safety_stock(self, art: ArticoloMagazzino, livello_servizio: float) -> float:        """Calcola SS = z * sqrt(L * sigma_d^2 + d^2 * sigma_L^2)."""        z = self.ottieni_fattore_z(livello_servizio)        varianza_nel_lt = (            art.lead_time_medio * (art.dev_std_domanda ** 2)            + (art.domanda_giornaliera ** 2) * (art.dev_std_lead_time ** 2)        )        return z * math.sqrt(varianza_nel_lt)    def calcola_rop(self, art: ArticoloMagazzino, safety_stock: float) -> float:        """Calcola ROP = d * L + SS."""        return (art.domanda_giornaliera * art.lead_time_medio) + safety_stock